export const BODY: string = "\n<p>ویب سائٹ سے ڈاؤن لوڈ شدہ WebP تصویر اکثر ترمیم، پرنٹ یا پرانے پروگرام میں کھولنے سے پہلے PNG بننی چاہیے۔ اسے بدلنے میں سیکنڈ لگتے ہیں، اور نتیجہ مکمل کاپی ہوتا ہے۔</p>\n<p>فکر کرنے والا کوئی کوالٹی سلائیڈر نہیں، کیونکہ PNG بغیر نقصان کا ہے۔ اپ لوڈ کریں، بدلیں اور ڈاؤن لوڈ کریں، اور پکسل بالکل محفوظ رہتے ہیں۔</p>\n<p>یہ رہنما ہر مرحلہ بتاتا ہے، ان جانچوں کے ساتھ جو تصدیق کرتی ہیں کہ تبدیلی درست ہوئی۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: جانیں آپ کیوں بدل رہے ہیں</h2>\n<p>خود سے پوچھیں PNG کس لیے ہے۔ ترمیم، پرنٹ اور پرانے سافٹ ویئر کے ساتھ مطابقت اچھی وجوہات ہیں۔ فائل چھوٹی کرنا نہیں، کیونکہ PNG WebP سے بڑی ہوتی ہے۔</p>\n<p>جانچیں کہ PNG واقعی ضروری ہے۔ کئی جدید ٹول WebP سیدھا قبول کرتے ہیں، اور PNG میں بدلنے سے تصویر بہتر ہوئے بغیر صرف سائز بڑھتا ہے۔</p>\n<p>بہترین WebP اصل تلاش کریں۔ PNG اسے بالکل محفوظ رکھے گا، خامیوں سمیت، اس لیے اعلیٰ ترین کوالٹی والی کاپی سے شروع کریں۔</p>\n<h2 id=\"step-1-open-tool\">مرحلہ 1: WebP سے PNG ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/webp-ko-png-mein-convert-karein/\">WebP to PNG ٹول</a> کھولیں۔ یہ صفحہ ونڈوز، میک، لینکس، کروم او ایس، اینڈرائیڈ اور آئی او ایس پر کام کرتا ہے۔</p>\n<p>آپ کو اپ لوڈ والا حصہ اور کنورٹ بٹن دکھائی دے گا۔ کوئی کوالٹی سلائیڈر نہیں، کیونکہ PNG بغیر نقصان کا ہے اور چننے کے لیے کوئی کوالٹی سطح نہیں۔</p>\n<p>اکاؤنٹ کی ضرورت نہیں ہے، اور کچھ بھی اپ لوڈ نہیں ہوتا۔ تبدیلی آپ کے آلے پر ہوتی ہے، جو ذاتی تصویروں اور ڈاؤن لوڈ شدہ فائلوں کے لیے اہم ہے۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی WebP فائلیں اپ لوڈ کریں</h2>\n<p>اپنی WebP فائلیں اپ لوڈ والے حصے پر گھسیٹ دیں، یا فائل پکر کھولنے کے لیے اس پر کلک کریں۔ بیچ کے لیے کئی فائلیں ایک ساتھ چن سکتے ہیں۔</p>\n<p>WebP سے PNG میں تبدیل ہونے والی ہر فائل اپنے کارڈ میں تھمب نیل، ابعاد اور سائز کے ساتھ سامنے آتی ہے، اور ایک نظر دیکھ کر ہی معلوم ہو جاتا ہے کہ کوئی اضافی فائل نہیں آئی۔</p>\n<p>کچھ ویب سائٹس تصویریں بغیر فائل ایکسٹینشن کے محفوظ کرتی ہیں۔ وہ فائلیں پھر بھی بدلتی ہیں، کیونکہ ٹول نام پر بھروسے کی بجائے اصل مواد پڑھتا ہے۔</p>\n<h2 id=\"step-3-convert\">مرحلہ 3: فائلیں بدلیں</h2>\n<p>Convert بٹن پر کلک کریں۔ ٹول ہر WebP کو ڈی کوڈ کرتا ہے، اسے کینوس پر بناتا ہے اور PNG کے طور پر انکوڈ کرتا ہے۔</p>\n<p>تبدیلی تیز ہوتی ہے، عام طور پر فی فائل ایک یا دو سیکنڈ۔ بڑی فائلیں تھوڑا زیادہ وقت لیتی ہیں، کیونکہ بغیر نقصان کے انکوڈ کرنے کے لیے زیادہ پکسل ہوتے ہیں۔</p>\n<p>ہر کارڈ پرانی WebP سائز کے ساتھ نیا PNG سائز دکھا کر اپ ڈیٹ ہوتا ہے۔ PNG کے کہیں بڑا ہونے کی توقع رکھیں، تصویروں کے لیے اکثر WebP سائز سے پانچ سے دس گنا۔</p>\n<h2 id=\"step-4-confirm-transparency\">مرحلہ 4: تصدیق کریں شفافیت بچ گئی</h2>\n<p>لوگو کارڈ پر Compare پر کلک کر کے WebP اور PNG ساتھ ساتھ دیکھیں۔ کناروں میں زوم کریں اور یقین کریں کہ شفافیت صاف لگتی ہے۔</p>\n<p>لوگو کے گرد ہالو یا کنارے دیکھیں۔ صاف کنارہ کا مطلب ہے الفا چینل بالکل نقل ہوا، جو آپ چاہتے ہیں۔</p>\n<p>نرم سائے بھی جانچیں۔ ڈراپ شیڈو تدریجی طور پر دھندلا ہونا چاہیے، نظر آنے والے بینڈ میں نہیں، جو غلطی بتاتے ہیں۔</p>\n<h2 id=\"step-5-download\">مرحلہ 5: PNG فائلیں ڈاؤن لوڈ کریں</h2>\n<p>ایک PNG محفوظ کرنے کے لیے کسی کارڈ پر Download پر کلک کریں۔ فائل نام آپ کا اصل نام .png ایکسٹینشن کے ساتھ رکھتا ہے۔</p>\n<p>بیچ کے لیے Download All پر کلک کر کے ایک ZIP لیں جس میں ہر بدلی ہوئی PNG ہو۔ یہ ایک ایک کر کے ڈاؤن لوڈ کرنے سے کہیں تیز ہے۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائلیں ایک بار جانچیں۔ PNG اپنے فوٹو ویور میں کھولیں اور یقین کریں کہ وہ درست لگتی ہے اور اس ایپ میں کھلتی ہے جسے اس کی ضرورت ہے۔</p>\n<ol>\n<li>WebP سے PNG ٹول کھولیں اور اپنی WebP فائلیں اپ لوڈ کریں۔</li>\n<li>Convert پر کلک کریں اور ہر کارڈ کے مکمل ہونے کا انتظار کریں۔</li>\n<li>Compare سے تصدیق کریں کہ شفافیت بچ گئی۔</li>\n<li>اکیلی PNG ڈاؤن لوڈ کریں یا پورا بیچ ZIP کے طور پر ڈاؤن لوڈ کریں۔</li>\n</ol>\n<h2 id=\"converting-a-batch\">WebP تصویروں کا بیچ بدلنا</h2>\n<p>فائل پکر میں کئی WebP فائلیں ایک ساتھ چنیں۔ وہ سب قطار میں لوڈ ہو جاتی ہیں، اور ایک کلک سے سب PNG میں بدل جاتی ہیں۔</p>\n<p>بیچ چلتے ہوئے کل سائز دیکھیں۔ WebP تصویروں کا بیچ PNG کے طور پر بہت بڑا ZIP بن سکتا ہے، اس لیے جانچیں کہ منزل اسے سنبھال سکتی ہے۔</p>\n<p>بیچ ڈاؤن لوڈ کرنے سے پہلے ایک یا دو فائلوں پر Compare ویور استعمال کریں۔ اس سے تصدیق ہوتی ہے کہ شفافیت بچ گئی اور رنگ میل کھاتے ہیں۔</p>\n<h2 id=\"using-png-for-editing\">ترمیم کے لیے PNG استعمال کرنا</h2>\n<p>PNG اپنے پسندیدہ ایڈیٹر میں کھولیں۔ فوٹوشاپ، فگما، کینوا اور پاورپوائنٹ سب PNG مقامی طور پر قبول کرتے ہیں، اور بغیر نقصان کا فارمیٹ بار بار محفوظ کرنے پر بھی سلامت رہتا ہے۔</p>\n<p>PNG ورژن میں اپنا متن، تشریحات یا اوورلے شامل کریں۔ ہر محفوظ کرنے پر تصویر بالکل اتنی ہی تیز رہتی ہے جتنی پچھلی بار، بغیر جمع ہونے والے نقصان کے۔</p>\n<p>تیار نتیجہ اس فارمیٹ میں برآمد کریں جو منزل کو چاہیے۔ ویب صفحہ WebP یا JPG چاہتا ہے، جبکہ پرنٹ شاپ خود PNG چاہ سکتی ہے۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر PNG توقع سے کہیں بڑا نکلے تو تصویروں کے لیے یہ عام ہے۔ PNG ہر پکسل بالکل محفوظ رکھتا ہے، اور تفصیلی تصویر کے لیے ایسا کرنے کو کئی بائٹ چاہییں۔</p>\n<p>اگر رنگ بدلے ہوئے لگیں تو ماخذ WebP میں کوئی رنگ پروفائل ہو سکتا ہے جو بچ نہ پایا۔ PNG کو WebP سے احتیاط سے موازنہ کریں، اور اگر فرق اہم ہو تو WebP رکھیں۔</p>\n<p>اگر کوئی فائل بدلنے میں ناکام ہو تو جانچیں کہ یہ واقعی WebP ہے۔ بغیر ایکسٹینشن والی فائل بھیس میں JPG یا PNG ہو سکتی ہے، اور ٹول فیصلہ کرنے کے لیے مواد پڑھتا ہے۔</p>\n<h2 id=\"mobile-tips\">فون اور ٹیبلٹ کے لیے نکات</h2>\n<p>فون پر اپ لوڈ والے حصے پر ٹیپ کریں اور اپنے ڈاؤن لوڈ یا گیلری سے WebP فائلیں چنیں۔ تبدیلی فون پر چلتی ہے، اور PNG آپ کے آلے پر ڈاؤن لوڈ ہوتی ہیں۔</p>\n<p>فون کے بیچ چھوٹے رکھیں، کیونکہ بڑی PNG موبائل پروسیسر پر انکوڈ ہونے میں وقت لیتی ہیں۔ ایک وقت میں پانچ فائلیں آرام دہ ہیں۔</p>\n<p>WebP سے PNG میں بدلی فائل فون کے Downloads فولڈر میں محفوظ ہو جاتی ہے۔ آئی فون پر Files ایپ سے دیکھیں، اینڈرائیڈ پر فائل مینیجر کھول کر چیک کریں۔</p>\n<h2 id=\"webp-for-photoshop\">فوٹوشاپ کے لیے WebP بدلنا</h2>\n<p>فوٹوشاپ اب WebP سپورٹ کرتا ہے، مگر کئی پلگ ان اور بیچ ایکشن اب بھی PNG کی توقع کرتے ہیں۔ درآمد سے پہلے PNG میں بدلنے سے وہ حیرانیاں بچتی ہیں جو ورک فلو توڑتی ہیں۔</p>\n<p>WebP فائلوں کو PNG میں بدلیں، پھر انہیں فوٹوشاپ میں کھولیں۔ بغیر نقصان کا فارمیٹ لیئر، ماسک اور ایڈجسٹمنٹ ہر محفوظ کرنے پر بغیر گراوٹ کے سنبھالتا ہے۔</p>\n<p>تصویروں کے بیچ کے لیے پہلے سب کو بدلیں، پھر PNG ایک ساتھ کھولیں۔ یہ ترتیب فوٹوشاپ سیشن ہموار رکھتی ہے، بجائے ہر فائل بدلنے کے لیے پراجیکٹ کے درمیان رکنے کے۔</p>\n<h2 id=\"webp-for-powerpoint\">پاورپوائنٹ کے لیے WebP بدلنا</h2>\n<p>پاورپوائنٹ کے پرانے ورژن WebP تصویریں نہیں دکھاتے، اس لیے WebP تصویر والی سلائیڈ پریزنٹیشن کمپیوٹر پر ٹوٹا آئیکن دکھا سکتی ہے۔ پہلے PNG میں بدلنے سے خطرہ ختم ہو جاتا ہے۔</p>\n<p>سلائیڈوں میں شامل کرنے سے پہلے WebP تصویروں کو PNG میں بدلیں۔ PNG ہر پاورپوائنٹ ورژن میں صاف ایمبیڈ ہوتی ہیں، اور سلائیڈیں کہیں بھی درست کھلتی ہیں۔</p>\n<p>کئی تصویروں والے ڈیک کے لیے پورا سیٹ ایک ساتھ بدلیں۔ بیچ تبدیلی میں منٹ لگتے ہیں، اور PNG سلائیڈوں میں ڈالنے کے لیے تیار ہوتی ہیں۔</p>\n<h2 id=\"webp-for-print-shop\">پرنٹ شاپ کے لیے WebP بدلنا</h2>\n<p>پرنٹ شاپس JPG یا PNG کی توقع کرتی ہیں، اور WebP فائل ان کے نظام سے مسترد ہو سکتی ہے۔ فائل بھیجنے سے پہلے PNG میں بدلیں، اور پہلے شاپ کی شرائط جانچیں۔</p>\n<p>پرنٹ کے لیے بدلتے ہوئے مکمل ریزولوشن رکھیں۔ 800 پکسل چوڑی ویب تصویر 3 انچ پر اچھی پرنٹ ہوتی ہے مگر 10 انچ پر خراب، اس لیے پرنٹ سائز کو پکسل گنتی سے ملائیں۔</p>\n<p>بدلنے کے بعد رنگ جانچیں، کیونکہ WebP اور PNG رنگ پروفائل کو تھوڑا مختلف سنبھالتے ہیں۔ فوری موازنہ تصدیق کرتا ہے کہ پرنٹ رنگ اسکرین رنگوں سے میل کھاتے ہیں۔</p>\n<h2 id=\"webp-for-form\">فارم کے لیے WebP بدلنا</h2>\n<p>اپ لوڈ فارم قابل قبول فارمیٹ کے طور پر JPG اور PNG درج کرتے ہیں، اور WebP فائل سیدھی واپس آ جاتی ہے۔ اپ لوڈ سے پہلے PNG میں بدلیں، اور پہلے فارم قواعد جانچیں۔</p>\n<p>زیادہ سے زیادہ فائل سائز مانگنے والے فارم کے لیے PNG بہت بڑا ہو سکتا ہے۔ PNG تصویر کئی میگا بائٹ ہو سکتی ہے، جبکہ وہی تصویر JPG کے طور پر اس کا حصہ ہوتی ہے۔</p>\n<p>اگر PNG بہت بڑا ہو تو WebP کو JPG میں بدلیں۔ <a href=\"/ur/webp-ko-jpg-mein-convert-karein/\">WebP to JPG کنورٹر</a> چھوٹی فائل بناتا ہے جو پھر بھی ہر جگہ کھلتی ہے۔</p>\n<h2 id=\"webp-from-chat\">چیٹ سے ملی WebP بدلنا</h2>\n<p>تصویریں اکثر چیٹ میں WebP فائلوں کے طور پر آتی ہیں، اور وہ آپ کے کمپیوٹر پر کھلنے سے انکار کر دیتی ہیں۔ دوست ویب سائٹ سے تصویر بھیجتا ہے، اور آپ کا فوٹو ویور ٹوٹا آئیکن دکھاتا ہے۔</p>\n<p>پہلے تصویر اپنے آلے پر محفوظ کریں، پھر اسے کنورٹر میں ڈالیں۔ چیٹ ایپ سے سیدھا بدلنا شاذ ہی کام کرتا ہے، کیونکہ فائل آپ کے آلے پر موجود ہونی چاہیے۔</p>\n<p>محفوظ کرنے کے بعد تصویر کی کوالٹی جانچیں۔ چیٹ ایپس اکثر تصویریں خود بخود کمپریس کرتی ہیں، اس لیے محفوظ شدہ فائل اصل سے پہلے سے کم کوالٹی کی ہو سکتی ہے۔</p>\n<h2 id=\"batch-for-project\">پراجیکٹ کے لیے بیچ بدلنا</h2>\n<p>پراجیکٹ کو اکثر WebP تصویروں کا پورا سیٹ ایک ساتھ PNG میں بدلنا ہوتا ہے۔ بیچ تبدیلی میں منٹ لگتے ہیں، اور PNG ڈیزائن ٹول میں ڈالنے کے لیے تیار ہوتی ہیں۔</p>\n<p>بدلنے سے پہلے تصویروں کو مقصد کے حساب سے ترتیب دیں۔ لوگو، تصویریں اور اسکرین شاٹ بعد میں مختلف ہینڈلنگ مانگ سکتے ہیں، اور پہلے ترتیب دینے سے پراجیکٹ منظم رہتا ہے۔</p>\n<p>بیچ ڈاؤن لوڈ کرنے سے پہلے ایک یا دو فائلوں پر Compare ویور استعمال کریں۔ اس سے تصدیق ہوتی ہے کہ شفافیت بچ گئی اور رنگ اصل سے میل کھاتے ہیں۔</p>\n<h2 id=\"webp-for-school-project\">اسکول پراجیکٹ کے لیے WebP بدلنا</h2>\n<p>اسکول پراجیکٹ کو اکثر ویب سے تصویریں چاہییں ہوتی ہیں، اور وہ تصویریں عام طور پر WebP ہوتی ہیں۔ پرانے سافٹ ویئر والا اسکول کمپیوٹر انہیں نہیں دکھا سکتا، اس لیے پہلے PNG میں بدلیں۔</p>\n<p>پراجیکٹ میں شامل کرنے سے پہلے تصویروں کو PNG میں بدلیں۔ PNG پاورپوائنٹ، ورڈ اور گوگل سلائیڈز میں صاف ایمبیڈ ہوتی ہیں، اور پراجیکٹ کسی بھی اسکول کمپیوٹر پر کھلتا ہے۔</p>\n<p>کئی تصویروں والے پراجیکٹ کے لیے پورا سیٹ ایک ساتھ بدلیں۔ بیچ تبدیلی میں منٹ لگتے ہیں، اور PNG سلائیڈوں میں ڈالنے کے لیے تیار ہوتی ہیں۔</p>\n<p>پورا طریقہ یہی ہے: اپ لوڈ کریں، بدلیں، تصدیق کریں، ڈاؤن لوڈ کریں۔ پس منظر کے لیے <a href=\"/ur/blog/webp-ko-png-rehnumai/\">WebP to PNG: Complete Guide</a> پڑھیں، اور ترمیم سوال کے لیے <a href=\"/ur/blog/webp-ko-png-editing-aur-compatibility/\">WebP to PNG: Editing, Transparency and Compatibility</a> دیکھیں۔ اگر آپ کو چھوٹی فائلیں چاہییں تو <a href=\"/ur/jpg-ko-webp-mein-convert-karein/\">JPG to WebP کنورٹر</a> بہتر ٹول ہے۔</p>\n";

